quests[43393] = { id = 43393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rising Shadows", description = "News of my return will spread fast among those who share my beliefs. Soon Azeroth will see the rise of Shadows, but I imagine this is not news to you.\n\nWhatever your plan may be, I hope it continues to see the Cult of Forgotten Shadows as allies.", completion = "The Forsaken will rejoice at Natalie Seline's return, and we will as well, knowing that the prophecy is being fulfilled.", objectives = "Return to Alonsus Faol at Netherlight Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43394] = { id = 43394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crossing Legion Lines", description = "I've received word from the Highlord that a group of paladins and priests were captured after a battle broke out at Felblaze Ingress. Your priestess, Delas Moonfang, was among those captured.\n\nThey've been taken through the demon portal and into the Legion stronghold of Niskara.\n\nWe will need the assistance of the Conclave if we have any hope of recovering them.", progress = "I've never been so happy to see you, {class}.", completion = "Thank the Light, {class}. I didn't want to give up hope.", objectives = "Use the demon portal at Felblaze Ingress to enter Niskara and find Aponi Brightmane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43395] = { id = 43395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allies of the Light", description = "Both Arator and Delas are still somewhere on this forsaken rock, as well as many of our other allies.\n\nWe cannot leave them, {name}.", completion = "I already heard of your heroism from Delas Moonfang. Thanks to you, many lives were saved.", objectives = "Save Silver Hand Knights or Conclave Priests, and rescue Arator the Redeemer and Delas Moonfang.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43396] = { id = 43396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mind of the Enemy", description = "The demon jailors spoke of an upcoming invasion. Their army is gathering for something big, and it worries me greatly.\n\nLet us find whatever information we can about their plans.", completion = "The intelligence you have gathered is further proof that the prophecy cannot be ignored. The Legion's attack is imminent, and we will not survive without the paladins as our allies under the Light.", objectives = "Find the Legion Intelligence, Star Map, and Image of Velen, then slay Brood Queen Aramis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43397] = { id = 43397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "United As One", description = "You and Delas have had dealings with the paladins before, maybe it's possible they will grant you an audience with their war council. \n\nHead to the Sanctum of Light and ask the paladins to help us defend Netherlight Temple from Balnazzar's attack.", progress = "Now is not the time for interruptions, {name}. The council needs to determine its course of action.", completion = "We will help defend Netherlight Temple and lay a trap for Balnazzar.", objectives = "Make your way to the Sanctum of Light to speak with Lady Liadrin, and hear the council of war.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43398] = { id = 43398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Alonsus Faol", objectives = "I knew from the moment we met in the quiet fields of Tirisfal that you would be the one to unite the priests.\n\nI'd like to take credit for finding our leader, but I really think the truth of it is, you found us.\n\nOur time together has only just begun, {name}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43399] = { id = 43399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortifying the Temple", description = "We've all worked so hard turning this temple into something all priests can be proud of, it would be a shame to see it fall to the Burning Legion.\n\nWe must strengthen our defenses in preparation for the attack. With the right resources, we can make the temple a nearly impenetrable fortress.", progress = "We will need to gather many resources in order to properly fortify the temple.", completion = "This should be enough to make the necessary improvements to our defenses.", objectives = "Complete 10 World Quests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43400] = { id = 43400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumenstone", description = "To prepare for the battle, we will need the best armor and weapons we can get.\n\nLumenstone is an enchanted material that can withstand great amounts of fel magic.\n\nIt is found in rare quantities all over the Broken Isles, and many of the native races use it in their own metalcrafting.\n\nWe should send our champions to target enemies around the Broken Isles - there should be plenty of Lumenstone to be found in their stockpiles.", progress = "Have you acquired any lumenstone?", completion = "There's enough lumenstone here to craft armor and weapons for an army. Nice work, {name}.", objectives = "Collect 50 Lumenstone by sending champions on \"Lumenstone\" missions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43401] = { id = 43401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Light in the Darkness", description = "The Burning Legion has begun their attack!\n\nI will remain here and prepare the temple's defenses. You must meet our allies in Dalaran and let them know that the battle has begun!\n\nMake haste, {name}. I do not know how long we will be able to keep Balnazzar at bay.", progress = "The paladins have always been our allies and friends. Now, we stand united against a common cause.", completion = "You fought well, High {class}.", objectives = "United with the paladins, defend Netherlight Temple and slay Lord Balnazzar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43402] = { id = 43402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Priest of Netherlight", description = "You have fulfilled the prophecy, but more than that, you have united the priests of Azeroth.\n\nWe should take a moment to recognize all that you have accomplished.", progress = "We rejoice in your triumph!", completion = "You are a leader worthy of our praise, High {class}.", objectives = "Listen as you are honored by the Conclave of priests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43403] = { id = 43403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending the Isles", description = "As druids, our charge is to defend nature... and in turn, our home, Azeroth.\n\nConflict breaks out all across the Broken Isles. The Burning Legion pushes forward, and numerous allies call out for our aid.\n\nWe must focus our efforts on defense, before we can mount an offense against the Nightmare.\n\nHelp our allies across the Broken Isles, then return to me when the situation is under control.", progress = "Conflict rages across the Broken Isles.", completion = "You have represented the Dreamgrove honorably, Archdruid. Your aid has helped many, and your victories will be spoken of for years to come.", objectives = "Complete 10 World Quests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43404] = { id = 43404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gathering for the Grand Master", description = "{name}, err... {class}t,\n\nYour presence is requested for a matter of the greatest importance at the Temple of Five Dawns.\n\nMaster Ponshu and the rest of the Broken Temple are waiting for you!", sourceObjective = "Report to Iron-Body Ponshu in the Temple of Five Dawns.", sourceObjectiveStatus = "unverified-source-field" }
quests[43405] = { id = 43405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da-Nel's Second Quest" }
quests[43406] = { id = 43406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Request for the Deathlord" }
quests[43407] = { id = 43407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Weapon", description = "I'm pleased to report that the improvements to the Soul Forge are complete!\n\nWhen you are ready, we shall use it to unlock the true potential of your weapon!", progress = "Suffer well, Deathlord.", completion = "May the new powers of your weapon serve you well.", objectives = "Approach the indicated location before the Soul Forge and raise your weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43408] = { id = 43408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summons for the Arch Druid" }
quests[43409] = { id = 43409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Weapon", description = "{class}t, in our short time together you have done much to aid the Circle.\n\nWe are inspired by your determination and have developed a new technique that will bind the power of your weapon with the Emerald Dream itself!\n\nEverything is prepared. When you are ready we shall begin.", progress = "We honor you, Archdruid.", completion = "With this new power, the Legion will fall!", objectives = "Approach the indicated location before the Seed of Ages and raise your weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43410] = { id = 43410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master is Requested" }
quests[43411] = { id = 43411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master is Requested" }
quests[43412] = { id = 43412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Weapon", description = "I'm pleased to report that the improvements to the Forge are complete!\n\nWhen you are ready, we shall use it to unlock the true potential of your weapon!", progress = "We honor you, Slayer.", completion = "May the new powers of your weapons serve you well.", objectives = "Approach the indicated location before the Cursed Forge of the Nathrezim and raise your weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43413] = { id = 43413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Twist in the Nether" }
quests[43414] = { id = 43414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Weapon", description = "{class}t, our research into the Felblood Altar has proven useful. We've developed a ritual that should unleash the full powers of your artifact weapon!\n\nSay the word, and we shall begin the ritual at once!", progress = "We honor you, Netherlord.", completion = "With this new power, nothing shall stop us!", objectives = "Approach the indicated location before the Felblood Altar and raise your weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43415] = { id = 43415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Weapon", description = "{class}t, in our short time together you have done much for our order.\n\nThrough your words and deeds we've been inspired to redouble our efforts and I'm proud to report that we've discovered a new technique that may be of use to you.\n\nIf you have a moment, {class}t, I would be pleased to show you the fruit of our research.", progress = "We honor you, Archmage.", completion = "May this power aid you in the times ahead.", objectives = "Approach the indicated location before the Forge of the Guardian and raise your weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43416] = { id = 43416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure" }
quests[43417] = { id = 43417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spirits Call" }
quests[43418] = { id = 43418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Weapon", description = "Farseer, since you have joined us you have done much to aid the Earthen Ring.\n\nYour efforts have not gone unnoticed. The spirits have watched all that you have done and are pleased. They also have shown me a technique that will unleash the true power of your weapon!\n\nThe ritual is ready. When you are prepared we can begin.", progress = "We honor you, Farseer.", completion = "May this power aid you in the times ahead.", objectives = "Approach the indicated location before the Ancient Elemental Altar and raise your weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43419] = { id = 43419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light Beckons" }
quests[43420] = { id = 43420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Weapon", description = "{class}t, in our short time together you have done much to aid the Conclave. Now, with the work upon the Altar of Light and Shadow complete, it is time that we aid you. We have discovered a method to awaken the full power of your weapon!\n\nPlease, step before the altar and raise your weapon high.", progress = "All hail the, High {class}!", completion = "May the new powers of your weapon serve you well.", objectives = "Approach the indicated location before the Altar of Light and Shadow and raise your weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43421] = { id = 43421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Raven Calls" }
quests[43422] = { id = 43422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Weapon", description = "I'm pleased to say that the improvements to the crucible are complete!\n\nWhen you are prepared, we shall use it to unlock the true potential of your weapons!", progress = "Well done, Shadowblade.", completion = "May your new weapons serve you well.", objectives = "Approach the indicated location before the Crucible of the Uncrowned and raise your weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43423] = { id = 43423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Weapon", description = "I'm pleased to say that the improvements to the Altar of the Eternal Hunt are complete!\n\nWhen you are ready, we shall use it to unlock the full potential of your weapon!", progress = "Well done, Huntmaster.", completion = "May the new powers of your weapon serve you well.", objectives = "Approach the indicated location before the Altar of the Eternal Hunt and raise your weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43424] = { id = 43424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Weapon", description = "{class}t, you've brought together the Silver Hand like no {class}t has done before. You've shown us that with determination and faith in the holy light we can overcome any challenge.\n\nFollowing in your example our workmen have toiled hard to improve the Altar of Ancient Kings, allowing it to unlock the true potential of your weapon.\n\nTheir work is now complete! Step forward when you are ready and we shall begin.", progress = "Well done, Highlord.", completion = "May this blessed power aid you in the times ahead.", objectives = "Approach the indicated location before the Altar of Ancient Kings and raise your weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43425] = { id = 43425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Weapon", description = "I've been watching you, {name}.\n\nTime and again you've led the Valarjar to war with your weapon held high! Time and again the halls of Valhalas have thundered with the cheers of your victory!\n\nNow that the enhancements to the forge have been completed, it is time that your weapon's true potential be unleashed! Meet with me at the forge, hero.", progress = "I honor you, Battlelord.", completion = "May your new weapon serve you well.", objectives = "Meet with Odyn at his forge and raise your weapon at the indicated location.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43426] = { id = 43426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Brogozog" }
