quests[43441] = { id = 43441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Second Weapon", description = "We have strong leads on other ancient weapons that you might choose to pursue, if having one renowned, powerful piece of history in your hands is somehow insufficient.\n\nI'll lay out the options for you. Let me know how you'd like to proceed.", completion = "It is decided then.", objectives = "Choose a second artifact to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
