quests[43604] = { id = 43604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maw of Souls: Ymiron's Broken Blade", description = "You hold King Ymiron's blade and realize what a fierce combatant he would make, were he to fight on your side.\n\nPerhaps Odyn could be persuaded to force the vrykul King's spirit to fight alongside your army.", completion = "Very well then.  Let it be done!", objectives = "Return to Skyhold and convince Odyn to raise King Ymiron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
