quests[43641] = { id = 43641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arcway: Wandering Plague" }
quests[43642] = { id = 43642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Rook Hold: The Sorrow" }
quests[43643] = { id = 43643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Axes", description = "Battlelord, I have a request. Find me inspiration! An axe whose form has seen a truly astounding amount of battle, wielded by one of the world's most powerful warriors. Both weapon and owner forged together in the crucible of war.\n\nFind this hero and their weapon, and convince them to come here.", progress = "You've found them?", completion = "Thank you, Battlelord. The Valarjar will be even better equipped once I've made my adjustments.\n\nIt has also inspired me to think of your weapon. The Blade Breaker. In my mind's eye the axe is called that.", objectives = "Search the Broken Isles for the greatest axe wielding warrior you know.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43644] = { id = 43644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Deeps", description = "I assure you the legends are true: Sharas'dal, the Scepter of Tides, was forged around living waters of the Well of Eternity. It gave Azshara dominion over life itself. I have sent shaman throughout the world looking for it, but the only one to ever find it has gone missing.\n\nWavespeaker Adelee said she had tracked the scepter to the Ruins of Vashj'ir, but we haven't heard from her since.\n\n{name}! Come with me to the ocean depths. Let's track down our missing shaman and get that artifact!", progress = "I can transport us to the depths. Step into the bubble here... It's mostly safe.", completion = "Very good!\n\nIf you haven't been to this realm before, I have learned a trick or two to give you your \"Sea Legs,\" allowing you to breathe underwater for the duration of our mission here.\n\nNow, let's find out missing {class} and the scepter she was looking for!", objectives = "Travel to the Ruins of Vashj'ir with Erunak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43645] = { id = 43645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wavespeaker's Trail", description = "The shaman we seek is Wavespeaker Adelee. Her research brought her down to these ancient ruins, where she reported naga armies amassing prior to the Legion invasion.\n\nThe last I had heard, she had located Sharas'dal, the Scepter of Tides - and then she went silent.\n\n{name}, Search for clues to her whereabouts among the lower level of the ruins. Beware the naga patrols!", progress = "How goes the search?", completion = "<You report your findings to Erunak, who listens distractedly while flipping through the journal you located.>\n\nSo... the naga have conscripted sea giants to their cause? This is disturbing.\n\nAdelee's journal confirms my fears. The naga have infiltrated the Abyssal Maw once again, and this time they have a powerful weapon with them: Sharas'dal. Our task is clear.", objectives = "Locate three clues to the whereabouts of Wavespeaker Adelee within the Ruins of Vashj'ir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[43646] = { id = 43646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Appearance Unlocked" }
